const payload = $('Email drafter request').first().json.body || {};
const output = $('Email drafter agent').first().json;
function text(value) {
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) return value.map(text).find(Boolean) || '';
  if (!value || typeof value !== 'object') return '';
  return value.output || value.text || value.output_text || value.content || text(value.message) || text(value.response) || '';
}
const raw = String(text(output)).replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
let parsed = {};
try { parsed = raw ? JSON.parse(raw) : {}; } catch { parsed = { body_text: raw }; }
const classification = payload.classification || {};
const priority = ['low', 'normal', 'high', 'urgent'].includes(parsed.priority) ? parsed.priority : (classification.priority || 'normal');
return [{ json: {
  should_generate_draft: parsed.should_generate_draft !== false,
  subject: parsed.subject || (payload.subject ? `Re: ${payload.subject}` : null),
  body_text: parsed.body_text || parsed.bodyText || parsed.body || parsed.reply || null,
  body_html: parsed.body_html || parsed.bodyHtml || null,
  topic: parsed.topic || classification.topic || null,
  priority,
  confidence: typeof parsed.confidence === 'number' ? parsed.confidence : null,
  escalation_reason: parsed.escalation_reason || null,
  raw_draft_output: output
}}];
